<?php defined('BASEPATH') OR exit('No direct script access allowed');$ocr=isset($inspection['ocr'])&&is_array($inspection['ocr'])?$inspection['ocr']:array(); ?>
<div class="lc-note"><strong>Pembacaan scan lokal</strong><p>Ekstraksi memberi saran teks dan kondisi; cocokkan dengan scan asli. Tidak menilai keaslian tanda tangan atau tanggung jawab kerusakan.</p><?php if($canInspect&&$inspection['status']==='draft'): ?><form method="post" action="<?= $actionUrl; ?>" data-lc-form><input type="hidden" name="action" value="inspection_extract"><input type="hidden" name="inspection_id" value="<?= (int)$inspection['id']; ?>"><button type="submit" class="secondary">Baca scan dengan OCR lokal</button></form><?php endif; ?></div>
<?php if(!empty($ocr['ok'])): ?><section class="lc-ref"><h3>Hasil ekstraksi · perlu verifikasi</h3><p class="muted">Mesin: <?= gh_lc_e(gh_lc_v($ocr,'engine')); ?>. Hasil ini belum mengubah status fasilitas.</p><?php foreach(isset($ocr['warnings'])?$ocr['warnings']:array() as $warning): ?><p class="lc-warning"><?= gh_lc_e($warning); ?></p><?php endforeach; ?><?php if(!empty($ocr['suggested_fields'])): ?><dl class="lc-kv"><?php foreach($ocr['suggested_fields'] as $field=>$value): ?><dt><?= gh_lc_e($field); ?></dt><dd><?= gh_lc_e($value); ?></dd><?php endforeach; ?></dl><?php endif; ?><?php if(!empty($ocr['items'])): ?><div class="lc-table-wrap"><table><thead><tr><th>Label fasilitas terbaca</th><th>Saran kondisi</th><th>Keyakinan pembacaan label</th></tr></thead><tbody><?php foreach($ocr['items'] as $suggestion): ?><tr><td><?= gh_lc_e(gh_lc_v($suggestion,'item_name')); ?></td><td><?= gh_lc_e(gh_lc_label(gh_lc_v($suggestion,'condition_status','uninspected'))); ?></td><td><?= isset($suggestion['confidence'])?gh_lc_e(round($suggestion['confidence']*100).'%'):'Perlu tinjau'; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?><details><summary>Teks mentah hasil pembacaan</summary><pre style="white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px"><?= gh_lc_e(gh_lc_v($ocr,'text','Tidak ada teks terbaca.')); ?></pre></details></section><?php endif; ?>
